                for attr in group:
                    value_formatted = format_value_simple(attr.value_str, indent)
                    if '\n' in value_formatted:
                        vlines = value_formatted.split('\n')
                        first = vlines[0]
                        rest = vlines[1:]
                        line = "  "*indent + f"{attr.key} = {first}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
                        for rl in rest:
                            lines.append(rl)
                    else:
