            elif val=='{':
                depth_brace+=1
            elif val=='}':
                depth_brace-=1
                if depth_brace <0:
                    depth_brace+=1
                    break
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1]=='}'):
                        break
                    else:
                        continue
                continue
            elif val=='(':
                depth_paren+=1
            elif val==')':
                depth_paren-=1
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
