                    nodes.append(Block(type_name, label_strs, inner_nodes, is_one_line=is_one_line))
                    i=new_idx
                    continue
                elif jt=='SYM' and jv=='=':
                    key = key_token[1]
                    j+=1
                    value_str, value_tokens, next_idx = parse_value(tokens, j)
