                    k=next_idx
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k < len(tokens) and tokens[k][0]=='COMMENT':
                        trailing = tokens[k][1]
                        next_idx = k+1
                    attr = Attribute(key, value_str, value_tokens)
                    attr.trailing_comment=trailing
                    nodes.append(attr)
                    i=next_idx
                    continue
                else:
                    i+=1
                    continue
            else:
                i+=1
                continue
        if typ=='SYM' and val=='{':
            j=i+1
            inner_nodes, new_idx = parse_body(tokens, j, is_root=False)
            if new_idx < len(tokens) and tokens[new_idx][0]=='SYM' and tokens[new_idx][1]=='}':
