            break
    res=""
    prev_val=None
    for idx,(typ,val) in enumerate(out_tokens):
        if typ=='COMMENT':
            if res and not res.endswith(' '):
                res+=' '
            res+=val
            continue
        if val==',':
            res+=','
            if idx+1 < len(out_tokens):
                nxt_typ,nxt_val = out_tokens[idx+1]
                if nxt_val not in (']', '}', ')'):
                    res+=' '
            prev_val=val
            continue
        if val in (']', ')'):
            res+=val
            prev_val=val
            continue
        if val=='}':
            if has_equals_in_braces and res and not res.endswith(' ') and not res.endswith('{'):
                res+=' '
            res+=val
            prev_val=val
            continue
        if val in ('[', '('):
            res+=val
            prev_val=val
            continue
        if val=='{':
            res+=val
            if has_equals_in_braces:
                if idx+1 < len(out_tokens):
                    nxt_typ,nxt_val = out_tokens[idx+1]
                    if nxt_val != '}':
                        res+=' '
            prev_val=val
            continue
        if val=='.':
            res+=val
            prev_val=val
            continue
        if val in ('=', '+', '-', '*', '/', '%', '==', '!=', '>=', '<=', '&&', '||', '>', '<', '?', ':', '=>', '!'):
            if res and not res.endswith(' ') and not res.endswith('(') and not res.endswith('[') and not res.endswith('{'):
                res+=' '
            res+=val
