def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ' or c == '\t':
            j = i
            while j < n and s[j] in ' \t':
                j+=1
            tokens.append(('WS', s[i:j], i))
            i=j
            continue
        if c == '\n':
            tokens.append(('NL', '\n', i))
            i+=1
            continue
        if c == '\r':
            if i+1 < n and s[i+1] == '\n':
                tokens.append(('NL', '\r\n', i))
                i+=2
            else:
                tokens.append(('NL', '\r', i))
                i+=1
            continue
        if c == '#':
            j = i
            while j < n and s[j] != '\n':
                j+=1
            tokens.append(('COMMENT', s[i:j], i))
            i=j
            continue
        if c == '/' and i+1 < n and s[i+1] == '/':
            j = i
            while j < n and s[j] != '\n':
                j+=1
            tokens.append(('COMMENT', s[i:j], i))
            i=j
            continue
        if c == '/' and i+1 < n and s[i+1] == '*':
            j = i+2
            while j < n:
                if s[j] == '*' and j+1 < n and s[j+1] == '/':
                    j+=2
                    break
                j+=1
            tokens.append(('COMMENT', s[i:j], i))
            i=j
            continue
        if c == '"':
            j = i+1
            depth_brace = 0
            in_interp = False
            while j < n:
                if not in_interp:
                    if s[j] == '\\':
                        j+=2
                        continue
                    if s[j] == '"':
                        j+=1
                        break
                    if s[j] == '$' and j+1 < n and s[j+1] == '{':
                        in_interp = True
                        depth_brace = 1
                        j+=2
                        continue
                    j+=1
                else:
                    if s[j] == '"':
                        k = j+1
                        while k < n:
                            if s[k] == '\\':
                                k+=2
                                continue
                            if s[k] == '"':
                                k+=1
                                break
                            k+=1
                        j = k
                        continue
                    if s[j] == '{':
                        depth_brace+=1
                        j+=1
                        continue
                    if s[j] == '}':
                        depth_brace-=1
                        j+=1
                        if depth_brace == 0:
                            in_interp = False
                        continue
                    if s[j] == '\\':
                        j+=2
                        continue
                    j+=1
            tokens.append(('STRING', s[i:j], i))
            i=j
            continue
        if c.isdigit() or (c == '-' and i+1 < n and s[i+1].isdigit()):
            j = i
            if s[j] == '-':
                j+=1
            while j < n and (s[j].isdigit() or s[j] in '.eE'):
                if s[j] in '+-':
                    if j>0 and s[j-1] in 'eE':
                        j+=1
                        continue
                    else:
                        break
                j+=1
            tokens.append(('NUMBER', s[i:j], i))
            i=j
            continue
        if c.isalpha() or c == '_' :
            j = i
            while j < n and (s[j].isalnum() or s[j] in '_-'):
                j+=1
            tokens.append(('IDENT', s[i:j], i))
            i=j
            continue
        two = s[i:i+2] if i+1 < n else ''
        if two in ('==', '!=', '>=', '<=', '&&', '||', '=>', '->', '...'):
            tokens.append(('OP', two, i))
            i+=2
            continue
        if c in '=:{ }[](),.:?+-%*/|&!<>':
            tokens.append(('SYM', c, i))
            i+=1
            continue
        tokens.append(('OTHER', c, i))
        i+=1
    return tokens

class Blank:
    def __init__(self, count):
        self.count=count
class Comment:
    def __init__(self, text):
        self.text=text
class Attribute:
    def __init__(self, key, value_str, raw_value_tokens):
        self.key=key
        self.value_str=value_str
        self.raw_tokens=raw_value_tokens
        self.trailing_comment=None
class Block:
    def __init__(self, type_name, labels, body, is_one_line=False, is_closed=True):
        self.type_name=type_name
        self.labels=labels
        self.body=body
        self.is_one_line=is_one_line
        self.is_closed=is_closed

def parse_value(tokens, idx):
    depth_square=0
    depth_brace=0
    depth_paren=0
    collected=[]
    j=idx
    while j < len(tokens) and tokens[j][0]=='WS':
        j+=1
    while j < len(tokens):
        typ,val,_ = tokens[j]
        if typ=='NL':
            if depth_square==0 and depth_brace==0 and depth_paren==0:
                break
            else:
                collected.append(tokens[j])
                j+=1
                continue
        if typ=='COMMENT':
            if depth_square==0 and depth_brace==0 and depth_paren==0:
                break
            else:
                collected.append(tokens[j])
                j+=1
                continue
        if typ=='SYM':
            if val=='[':
                depth_square+=1
            elif val==']':
                depth_square-=1
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1] in ('}', ']', ',')):
                        break
                    else:
                        continue
                continue
            elif val=='{':
                depth_brace+=1
            elif val=='}':
                depth_brace-=1
                if depth_brace <0:
                    depth_brace+=1
                    break
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1] in ('}', ']', ',')):
                        break
                    else:
                        continue
                continue
            elif val=='(':
                depth_paren+=1
            elif val==')':
                depth_paren-=1
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1] in ('}', ']', ',')):
                        break
                    else:
                        continue
                continue
            elif val==',':
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    break
                else:
                    collected.append(tokens[j])
                    j+=1
                    continue
        collected.append(tokens[j])
        j+=1
    raw_str = ''.join(t[1] for t in collected)
    return raw_str.strip(), collected, j

def parse_body(tokens, idx, is_root=True):
    nodes=[]
    i=idx
    while i < len(tokens):
        typ,val,_ = tokens[i]
        if typ=='WS':
            i+=1
            continue
        if typ=='NL':
            cnt=0
            while i < len(tokens) and tokens[i][0] in ('WS','NL'):
                if tokens[i][0]=='NL':
                    cnt+=1
                i+=1
            if cnt>1:
                nodes.append(Blank(cnt-1))
            continue
        if typ=='COMMENT':
            nodes.append(Comment(val))
            i+=1
            continue
        if typ=='SYM' and val==',':
            i+=1
            while i < len(tokens) and tokens[i][0]=='WS':
                i+=1
            continue
        if typ=='SYM' and val=='}':
