def format_nodes(nodes, indent=0):
    lines=[]
    i=0
    while i < len(nodes):
        node = nodes[i]
        if isinstance(node, Blank):
            for _ in range(node.count):
                lines.append("")
            i+=1
            continue
        if isinstance(node, Comment):
            lines.append("  "*indent + node.text.strip())
            i+=1
            continue
        if isinstance(node, Attribute):
            group=[]
            j=i
            while j < len(nodes):
                n = nodes[j]
                if isinstance(n, Attribute):
                    group.append(n)
                    j+=1
                else:
                    break
            has_multiline = any('\n' in g.value_str for g in group)
            if has_multiline:
                for attr in group:
                    value_formatted = format_value_simple(attr.value_str, indent)
                    if '\n' in value_formatted:
                        vlines = value_formatted.split('\n')
                        first = vlines[0]
                        rest = vlines[1:]
                        line = "  "*indent + f"{attr.key} = {first}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
                        for rl in rest:
                            lines.append(rl)
                    else:
                        line = "  "*indent + f"{attr.key} = {value_formatted}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
            else:
                max_key_len = max(len(g.key) for g in group) if group else 0
                for attr in group:
                    padded_key = attr.key.ljust(max_key_len)
                    value_formatted = format_value_simple(attr.value_str, indent)
                    if '\n' in value_formatted:
                        vlines = value_formatted.split('\n')
                        first = vlines[0]
                        rest = vlines[1:]
                        line = "  "*indent + f"{padded_key} = {first}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
                        for rl in rest:
                            lines.append(rl)
                    else:
                        line = "  "*indent + f"{padded_key} = {value_formatted}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
            i=j
            continue
        if isinstance(node, Block):
            header = node.type_name
            if header:
                if node.labels:
                    header += " " + " ".join(node.labels)
                header += " {"
            else:
                header += "{"
            if node.is_one_line:
                if not node.body:
                    if header.endswith(" {"):
                        if node.is_closed:
                            lines.append("  "*indent + header[:-2] + " {}")
                        else:
                            lines.append("  "*indent + header)
                    else:
                        lines.append("  "*indent + ("{}" if node.is_closed else "{"))
                else:
                    inner_parts=[]
                    for bnode in node.body:
                        if isinstance(bnode, Attribute):
                            inner_parts.append(f"{bnode.key} = {format_value_simple(bnode.value_str, 0)}")
                        elif isinstance(bnode, Block):
                            inner_parts.append(" ".join(format_nodes([bnode], 0)))
                        elif isinstance(bnode, Comment):
                            inner_parts.append(bnode.text.strip())
                    inner_str = " ".join(inner_parts)
                    if header.endswith(" {"):
                        base = header[:-2]
                        if node.is_closed:
                            lines.append("  "*indent + f"{base} {{ {inner_str} }}")
                        else:
                            lines.append("  "*indent + f"{base} {{ {inner_str}")
                    else:
                        closing = " }" if node.is_closed else ""
                        lines.append("  "*indent + f"{{ {inner_str}{closing}")
            else:
                lines.append("  "*indent + header)
                inner_lines = format_nodes(node.body, indent+1)
                lines.extend(inner_lines)
                if node.is_closed:
                    lines.append("  "*indent + "}")
            i+=1
            continue
        i+=1
    return lines

def fmt_file(content):
    has_trailing_nl = content.endswith('\n') or content.endswith('\r\n') or content.endswith('\r')
    if content.strip() == "":
        return content
    toks = tokenize(content)
    nodes, _ = parse_body(toks, 0, is_root=True)
    lines = format_nodes(nodes, 0)
    result = "\n".join(lines)
    if result:
        if has_trailing_nl:
            if not result.endswith('\n'):
                result += '\n'
        else:
            if result.endswith('\n'):
                result = result.rstrip('\n')
    else:
        if content.strip() == "":
            return content
    return result
