                    inner_lines = format_nodes(nodes, indent+1)
                    if inner_lines:
                        return "{\n" + "\n".join(inner_lines) + "\n" + "  "*indent + "}"
                    else:
                        return "{\n" + "  "*indent + "}"
                else:
                    inner_toks = tokenize(inner_content)
                    nodes, _ = parse_body(inner_toks, 0, is_root=True)
                    if not nodes:
                        return "{}"
                    first_node = nodes[0]
                    rest_nodes = nodes[1:]
                    if isinstance(first_node, Attribute):
                        first_fmt = f"{first_node.key} = {format_value_simple(first_node.value_str, 0)}"
                        if first_node.trailing_comment:
