def parse_body(tokens, idx, is_root=True):
    nodes=[]
    i=idx
    while i < len(tokens):
        typ,val,_ = tokens[i]
        if typ=='WS':
            i+=1
            continue
        if typ=='NL':
            cnt=0
            while i < len(tokens) and tokens[i][0] in ('WS','NL'):
                if tokens[i][0]=='NL':
