class Block:
    def __init__(self, type_name, labels, body, is_one_line=False, is_closed=True, has_nl_after_open=True):
        self.type_name=type_name
        self.labels=labels
        self.body=body
        self.is_one_line=is_one_line
        self.is_closed=is_closed
        self.has_nl_after_open=has_nl_after_open

def parse_value(tokens, idx):
    depth_square=0
    depth_brace=0
    depth_paren=0
    collected=[]
    j=idx
    while j < len(tokens) and tokens[j][0]=='WS':
        j+=1
    while j < len(tokens):
        typ,val,_ = tokens[j]
        if typ=='NL':
            if depth_square==0 and depth_brace==0 and depth_paren==0:
                break
