                collected.append(tokens[j])
                j+=1
                continue
        if typ=='COMMENT':
            if depth_square==0 and depth_brace==0 and depth_paren==0:
                break
            else:
                collected.append(tokens[j])
                j+=1
                continue
        if typ=='SYM':
            if val=='[':
                depth_square+=1
            elif val==']':
                depth_square-=1
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1] in ('}', ']', ',')):
                        break
                    else:
                        continue
                continue
            elif val=='{':
                depth_brace+=1
            elif val=='}':
                depth_brace-=1
                if depth_brace <0:
                    depth_brace+=1
                    break
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1] in ('}', ']', ',')):
                        break
                    else:
                        continue
                continue
            elif val=='(':
                depth_paren+=1
            elif val==')':
                depth_paren-=1
                collected.append(tokens[j])
                j+=1
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    k=j
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k>=len(tokens) or tokens[k][0] in ('NL','COMMENT') or (tokens[k][0]=='SYM' and tokens[k][1] in ('}', ']', ',')):
                        break
                    else:
                        continue
                continue
            elif val==',':
                if depth_square==0 and depth_brace==0 and depth_paren==0:
                    break
                else:
                    collected.append(tokens[j])
                    j+=1
                    continue
        collected.append(tokens[j])
        j+=1
    raw_str = ''.join(t[1] for t in collected)
    return raw_str.strip(), collected, j

def parse_body(tokens, idx, is_root=True):
    nodes=[]
    i=idx
    while i < len(tokens):
        typ,val,_ = tokens[i]
        if typ=='WS':
            i+=1
            continue
        if typ=='NL':
            cnt=0
            while i < len(tokens) and tokens[i][0] in ('WS','NL'):
                if tokens[i][0]=='NL':
                    cnt+=1
                i+=1
            if cnt>1:
                nodes.append(Blank(cnt-1))
            continue
        if typ=='COMMENT':
            nodes.append(Comment(val))
            i+=1
            continue
        if typ=='SYM' and val==',':
            i+=1
            while i < len(tokens) and tokens[i][0]=='WS':
                i+=1
            continue
        if typ=='SYM' and val=='}':
            if not is_root:
                return nodes, i
            else:
                i+=1
                continue
        if typ in ('IDENT','STRING'):
            j=i
            key_token = tokens[j]
            j+=1
            while j < len(tokens) and tokens[j][0]=='WS':
                j+=1
            labels=[]
            while j < len(tokens):
                ttyp,tval,_ = tokens[j]
                if ttyp in ('STRING','IDENT'):
                    k=j+1
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k < len(tokens):
                        ktyp,kval,_ = tokens[k]
                        if ktyp in ('STRING','IDENT') or (ktyp=='SYM' and kval=='{'):
                            labels.append((ttyp,tval))
                            j=k
                            while j < len(tokens) and tokens[j][0]=='WS':
                                j+=1
                            if j < len(tokens) and tokens[j][0]=='SYM' and tokens[j][1]=='{':
                                break
                            elif j < len(tokens) and tokens[j][0] in ('STRING','IDENT'):
                                continue
                            elif j < len(tokens) and tokens[j][0]=='SYM' and tokens[j][1]=='=':
                                break
                            else:
                                break
                        elif ktyp=='SYM' and kval=='=':
                            break
                        else:
                            break
                    else:
                        break
                elif ttyp=='SYM' and tval=='{':
                    break
                elif ttyp=='SYM' and tval=='=':
                    break
                else:
                    break
            if j < len(tokens):
                jt,jv,_ = tokens[j]
                if jt=='SYM' and jv=='{':
                    type_name = key_token[1] if key_token[0]=='IDENT' else key_token[1]
                    label_strs = [l[1] for l in labels]
                    j+=1
                    k=j
                    has_nl_after_open = False
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k < len(tokens) and tokens[k][0]=='NL':
                        has_nl_after_open = True
                    inner_nodes, new_idx = parse_body(tokens, j, is_root=False)
                    is_closed = False
                    if new_idx < len(tokens) and tokens[new_idx][0]=='SYM' and tokens[new_idx][1]=='}':
                        is_closed = True
                        new_idx+=1
                    has_nl=False
                    for t in tokens[j:new_idx]:
                        if t[0]=='NL':
                            has_nl=True
                            break
                    is_one_line = not has_nl
                    nodes.append(Block(type_name, label_strs, inner_nodes, is_one_line=is_one_line, is_closed=is_closed, has_nl_after_open=has_nl_after_open))
                    i=new_idx
                    continue
                elif jt=='SYM' and jv=='=':
                    key = key_token[1]
                    j+=1
                    value_str, value_tokens, next_idx = parse_value(tokens, j)
                    trailing=None
                    k=next_idx
                    while k < len(tokens) and tokens[k][0]=='WS':
                        k+=1
                    if k < len(tokens) and tokens[k][0]=='COMMENT':
                        trailing = tokens[k][1]
                        next_idx = k+1
                    attr = Attribute(key, value_str, value_tokens)
                    attr.trailing_comment=trailing
                    nodes.append(attr)
                    i=next_idx
                    continue
                else:
                    i+=1
                    continue
            else:
                i+=1
                continue
        if typ=='SYM' and val=='{':
            j=i+1
            k=j
            has_nl_after_open = False
            while k < len(tokens) and tokens[k][0]=='WS':
                k+=1
            if k < len(tokens) and tokens[k][0]=='NL':
                has_nl_after_open = True
            inner_nodes, new_idx = parse_body(tokens, j, is_root=False)
            is_closed = False
            if new_idx < len(tokens) and tokens[new_idx][0]=='SYM' and tokens[new_idx][1]=='}':
                is_closed = True
                new_idx+=1
            has_nl=False
            for t in tokens[j:new_idx]:
                if t[0]=='NL':
                    has_nl=True
                    break
            is_one_line = not has_nl
            nodes.append(Block("", [], inner_nodes, is_one_line=is_one_line, is_closed=is_closed, has_nl_after_open=has_nl_after_open))
            i=new_idx
            continue
        i+=1
    return nodes, i

def format_value_simple(value_str, indent):
    stripped = value_str.strip()
    if not stripped:
        return ""
    if '\n' in value_str:
        if stripped.startswith('{') and stripped.endswith('}'):
            inner_content = stripped[1:-1]
            if '=' in inner_content or inner_content.strip()=='':
                toks = tokenize(value_str)
                idx_open = None
                for idx_t, (ttyp,tval,_) in enumerate(toks):
                    if ttyp=='SYM' and tval=='{':
                        idx_open = idx_t
                        break
                has_nl_after_open = False
                if idx_open is not None:
                    k = idx_open+1
                    while k < len(toks) and toks[k][0]=='WS':
                        k+=1
                    if k < len(toks) and toks[k][0]=='NL':
                        has_nl_after_open = True
                if has_nl_after_open:
                    inner_toks = tokenize(inner_content)
                    nodes, _ = parse_body(inner_toks, 0, is_root=True)
                    inner_lines = format_nodes(nodes, indent+1)
                    if inner_lines:
                        return "{\n" + "\n".join(inner_lines) + "\n" + "  "*indent + "}"
                    else:
                        return "{\n" + "  "*indent + "}"
                else:
                    inner_toks = tokenize(inner_content)
                    nodes, _ = parse_body(inner_toks, 0, is_root=True)
                    if not nodes:
                        return "{}"
                    first_node = nodes[0]
                    rest_nodes = nodes[1:]
                    if isinstance(first_node, Attribute):
                        first_fmt = f"{first_node.key} = {format_value_simple(first_node.value_str, 0)}"
                        if first_node.trailing_comment:
                            first_fmt += " " + first_node.trailing_comment.strip()
                    else:
                        first_fmt = format_nodes([first_node], 0)[0] if format_nodes([first_node], 0) else ""
                    rest_lines = format_nodes(rest_nodes, indent) if rest_nodes else []
                    if rest_lines:
                        return "{ " + first_fmt + ",\n" + "\n".join(rest_lines) + "\n" + "  "*indent + "}"
                    else:
                        return "{ " + first_fmt + " }"
        if stripped.startswith('[') and stripped.endswith(']'):
            toks = tokenize(value_str)
            idx_bracket = None
            for idx_t, (ttyp,tval,_) in enumerate(toks):
                if ttyp=='SYM' and tval=='[':
                    idx_bracket = idx_t
                    break
            has_nl_after_bracket = False
            if idx_bracket is not None:
                k = idx_bracket+1
                while k < len(toks) and toks[k][0]=='WS':
                    k+=1
                if k < len(toks) and toks[k][0]=='NL':
                    has_nl_after_bracket = True
            elements = []
            cur_elem_tokens=[]
            depth=0
            i = idx_bracket+1 if idx_bracket is not None else 0
            while i < len(toks):
                ttyp,tval,_ = toks[i]
                if ttyp=='SYM' and tval=='[':
                    depth+=1
                    cur_elem_tokens.append(toks[i])
                elif ttyp=='SYM' and tval==']' and depth==0:
                    if cur_elem_tokens:
                        has_content = any(t[0] not in ('WS','NL',) for t in cur_elem_tokens)
                        if has_content:
                            elements.append(cur_elem_tokens)
                    break
                elif ttyp=='SYM' and tval==']':
                    depth-=1
                    cur_elem_tokens.append(toks[i])
                elif ttyp=='SYM' and tval==',' and depth==0:
                    elements.append(cur_elem_tokens)
                    cur_elem_tokens=[]
                else:
                    cur_elem_tokens.append(toks[i])
                i+=1
            formatted_elements = []
            for elem_toks in elements:
                raw = ''.join(t[1] for t in elem_toks)
                if raw.strip()=='':
                    continue
                fmt_elem = format_value_simple(raw, 0)
                formatted_elements.append(fmt_elem)
            if has_nl_after_bracket:
                if formatted_elements:
                    inner_lines = []
                    for idx_e, fe in enumerate(formatted_elements):
                        is_last = idx_e == len(formatted_elements)-1
                        comma = "" if is_last else ","
                        inner_lines.append("  "*(indent+1) + fe + comma)
                    return "[\n" + "\n".join(inner_lines) + "\n" + "  "*indent + "]"
                else:
                    return "[\n" + "  "*indent + "]"
            else:
                if not formatted_elements:
                    return "[]"
                result = "[" + formatted_elements[0] + ","
                for fe in formatted_elements[1:]:
                    is_last = fe == formatted_elements[-1]
                    comma = "" if is_last else ","
                    result += "\n" + "  "*(indent+1) + fe + comma
                result += "\n" + "  "*indent + "]"
                return result
    toks = tokenize(value_str)
    out_tokens=[]
    for typ,val,_ in toks:
        if typ in ('WS','NL'):
            continue
        out_tokens.append((typ,val))
    has_equals_in_braces = False
    brace_depth=0
    for t,v in out_tokens:
        if v=='{':
            brace_depth+=1
        elif v=='}':
            brace_depth-=1
        elif v=='=' and brace_depth>0:
            has_equals_in_braces=True
            break
    res=""
    prev_val=None
    for idx,(typ,val) in enumerate(out_tokens):
        if typ=='COMMENT':
            if res and not res.endswith(' '):
                res+=' '
            res+=val
            continue
        if val==',':
            res+=','
            if idx+1 < len(out_tokens):
                nxt_typ,nxt_val = out_tokens[idx+1]
                if nxt_val not in (']', '}', ')'):
                    res+=' '
            prev_val=val
            continue
        if val in (']', ')'):
            res+=val
            prev_val=val
            continue
        if val=='}':
            if has_equals_in_braces and res and not res.endswith(' ') and not res.endswith('{'):
                res+=' '
            res+=val
            prev_val=val
            continue
        if val in ('[', '('):
            res+=val
            prev_val=val
            continue
        if val=='{':
            res+=val
            if has_equals_in_braces:
                if idx+1 < len(out_tokens):
                    nxt_typ,nxt_val = out_tokens[idx+1]
                    if nxt_val != '}':
                        res+=' '
            prev_val=val
            continue
        if val=='.':
            res+=val
            prev_val=val
            continue
        if val in ('=', '+', '-', '*', '/', '%', '==', '!=', '>=', '<=', '&&', '||', '>', '<', '?', ':', '=>', '!'):
            if res and not res.endswith(' ') and not res.endswith('(') and not res.endswith('[') and not res.endswith('{'):
                res+=' '
            res+=val
            if idx+1 < len(out_tokens):
                nxt_typ,nxt_val = out_tokens[idx+1]
                if nxt_val not in (',', ')', ']', '}', ':', '?', '.', '%'):
                    res+=' '
            prev_val=val
            continue
        if res and not res.endswith(' ') and not res.endswith('(') and not res.endswith('[') and not res.endswith('{') and not res.endswith('.'):
            if prev_val not in ('(', '[', '{', '.', ',', '=', '+', '-', '*', '/', '%', '==', '!=', '>=', '<=', '&&', '||', '>', '<', '?', ':', '=>', '!'):
                if not res.endswith(' '):
                    res+=' '
        res+=val
        prev_val=val
    return res.strip()

def format_nodes(nodes, indent=0):
    lines=[]
    i=0
    while i < len(nodes):
        node = nodes[i]
        if isinstance(node, Blank):
            for _ in range(node.count):
                lines.append("")
            i+=1
            continue
        if isinstance(node, Comment):
            lines.append("  "*indent + node.text.strip())
            i+=1
            continue
        if isinstance(node, Attribute):
            group=[]
            j=i
            while j < len(nodes):
                n = nodes[j]
                if isinstance(n, Attribute):
                    group.append(n)
                    j+=1
                else:
                    break
            has_multiline = any('\n' in g.value_str for g in group)
            if has_multiline:
                for attr in group:
                    value_formatted = format_value_simple(attr.value_str, indent)
                    if '\n' in value_formatted:
                        vlines = value_formatted.split('\n')
                        first = vlines[0]
                        rest = vlines[1:]
                        line = "  "*indent + f"{attr.key} = {first}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
                        for rl in rest:
                            lines.append(rl)
                    else:
                        line = "  "*indent + f"{attr.key} = {value_formatted}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
            else:
                max_key_len = max(len(g.key) for g in group) if group else 0
                for attr in group:
                    padded_key = attr.key.ljust(max_key_len)
                    value_formatted = format_value_simple(attr.value_str, indent)
                    if '\n' in value_formatted:
                        vlines = value_formatted.split('\n')
                        first = vlines[0]
                        rest = vlines[1:]
                        line = "  "*indent + f"{padded_key} = {first}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
                        for rl in rest:
                            lines.append(rl)
                    else:
                        line = "  "*indent + f"{padded_key} = {value_formatted}"
                        if attr.trailing_comment:
                            line += " " + attr.trailing_comment.strip()
                        lines.append(line)
            i=j
            continue
        if isinstance(node, Block):
            header = node.type_name
            if header:
                if node.labels:
                    header += " " + " ".join(node.labels)
                header += " {"
            else:
                header += "{"
            if node.is_one_line:
                if not node.body:
                    if header.endswith(" {"):
                        if node.is_closed:
                            lines.append("  "*indent + header[:-2] + " {}")
                        else:
                            lines.append("  "*indent + header)
                    else:
                        lines.append("  "*indent + ("{}" if node.is_closed else "{"))
                else:
                    inner_parts=[]
                    for bnode in node.body:
                        if isinstance(bnode, Attribute):
                            inner_parts.append(f"{bnode.key} = {format_value_simple(bnode.value_str, 0)}")
                        elif isinstance(bnode, Block):
                            inner_parts.append(" ".join(format_nodes([bnode], 0)))
                        elif isinstance(bnode, Comment):
                            inner_parts.append(bnode.text.strip())
                    inner_str = " ".join(inner_parts)
                    if header.endswith(" {"):
                        base = header[:-2]
                        if node.is_closed:
                            lines.append("  "*indent + f"{base} {{ {inner_str} }}")
                        else:
                            lines.append("  "*indent + f"{base} {{ {inner_str}")
                    else:
                        closing = " }" if node.is_closed else ""
                        lines.append("  "*indent + f"{{ {inner_str}{closing}")
            else:
                if not node.has_nl_after_open and node.body:
                    first = node.body[0]
                    rest = node.body[1:]
                    first_lines = format_nodes([first], 0)
                    if first_lines:
                        combined = "  "*indent + header + " " + first_lines[0].lstrip()
                        lines.append(combined)
                        if len(first_lines)>1:
                            for fl in first_lines[1:]:
                                # fl already has indent 0 or more? Need to adjust to indent+1?
                                # first_lines were formatted with indent 0, but we need them at indent+1 for subsequent lines
                                # For bare block case, first_lines[1] is "}", which should be at indent+1?
                                # Let's add indent+1 for remaining lines of first
                                lines.append("  "*(indent+1) + fl.lstrip())
                        inner_rest = format_nodes(rest, indent+1)
                        lines.extend(inner_rest)
                        if node.is_closed:
                            lines.append("  "*indent + "}")
                    else:
                        lines.append("  "*indent + header)
                        inner_lines = format_nodes(node.body, indent+1)
                        lines.extend(inner_lines)
                        if node.is_closed:
                            lines.append("  "*indent + "}")
                else:
                    lines.append("  "*indent + header)
                    inner_lines = format_nodes(node.body, indent+1)
                    lines.extend(inner_lines)
                    if node.is_closed:
                        lines.append("  "*indent + "}")
            i+=1
            continue
        i+=1
    return lines

def fmt_file(content):
    has_trailing_nl = content.endswith('\n') or content.endswith('\r\n') or content.endswith('\r')
    if content.strip() == "":
        return content
    toks = tokenize(content)
    nodes, _ = parse_body(toks, 0, is_root=True)
    lines = format_nodes(nodes, 0)
    result = "\n".join(lines)
    if result:
        if has_trailing_nl:
            if not result.endswith('\n'):
                result += '\n'
        else:
            if result.endswith('\n'):
                result = result.rstrip('\n')
    else:
        if content.strip() == "":
            return content
    return result

